-- GenDB engine variant Q22-commuted_comparisons: template q22.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  cntrycode,
  COUNT(*) AS numcust,
  SUM(c_acctbal) AS totacctbal
FROM (
  SELECT
    SUBSTRING(c_phone FROM 1 FOR 2) AS cntrycode,
    c_acctbal
  FROM customer
  WHERE
    SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    AND (
      SELECT
        AVG(c_acctbal)
      FROM customer
      WHERE
        0.00 < c_acctbal
        AND SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    ) < c_acctbal
    AND NOT EXISTS(
      SELECT
        *
      FROM orders
      WHERE
        c_custkey = o_custkey
    )
) AS custsale
GROUP BY
  cntrycode
ORDER BY
  cntrycode
